sys_variable_value.value:
(function execute(inputs, outputs) {

        var token_primary = inputs.token;
    var payload_primary = inputs.payload;

    try {
        var tokenBearer = token_primary;
        var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'adicionarVigencia');

        r.setEndpoint(getEndpoint() + '/contracts/addendum');
        r.setStringParameterNoEscape('token', tokenBearer);
        r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
        r.setRequestHeader('Content-Type', 'application/json');

        var requestBody = payload_primary;
        r.setRequestBody(requestBody);

        gs.info('###Contratos - Desconto ' + requestBody);

        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
            gs.info('Contrato OK ' + responseBody);

            var responseObject = JSON.parse(responseBody);
            var contractNumberAnswer = responseObject.ContractNumber;
            var returnCode = responseObject.ReturnCode;
            var messageDescription = responseObject.MessageDescription;
            var companyCodeAnswer = responseObject.CompanyCode;

            gs.info('###Contratos ContractNumber: ' + contractNumberAnswer);
            gs.info('###Contratos ReturnCode: ' + returnCode);
            gs.info('###Contratos MessageDescription: ' + messageDescription);
            gs.info('###Contratos CompanyCode: ' + companyCodeAnswer);

            outputs.contractnumberanswer = contractNumberAnswer;
            outputs.returncode = returnCode;
            outputs.messagedescription = messageDescription;
            outputs.companycodeanswer = companyCodeAnswer;
			
        } else {
            gs.info('Else: ' + httpStatus);

            var arrError = [];
            var responseObjectElse = JSON.parse(responseBody);
            outputs.httpstatus = httpStatus;

            for (var i = 0; i < responseObjectElse.ReturnMessages.length; i++) {
                var message = responseObjectElse.ReturnMessages[i];
                arrError.push(message.Message);

            }
            if (arrError.length > 0) {
                var errorOut = arrError.join("; ");
                outputs.erroroutput = errorOut;
                gs.info("Erros encontrados: " + errorOut);
            } else {
                var errorMsg = responseObjectElse.ReturnMessages[i]
                gs.info("Nenhum erro encontrado.");
            }

            if (responseObjectElse.ReturnMessages && responseObjectElse.ReturnMessages.length > 0) {
            outputs.erroroutput = responseObjectElse.ReturnMessages[0].Message;
            gs.info("Erro encontrado: " + outputs.erroroutput);
} 
        }
    } catch (ex) {
        var message = ex.message;
    }



    function getEndpoint() {
        var instanceName = gs.getProperty('instance_name');

        if (instanceName == 'allos') {
            gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd'));
            return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd');
        } else {
            gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa'));
            return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa');
        }
    }

})(inputs, outputs);

